/**
 * THE RETIRED ADMIN PAGES (S1 #4796; `INV-SSOT`).
 *
 * The five pages the owner approved merging on #4468 (1 Nov 2026, "merges as
 * in the LANE-SYNC"). Each one's content now lives in the page it was merged
 * into, and its old URL redirects there, query kept (a 307 for its first
 * release, permanent one release later, so a rollback is safe): the rule is
 * generated by `buildAdminUrlRules` from this list, so the redirect, the page's
 * tab and every link to it are read from the registry and cannot disagree.
 *
 * Every page here was admitted on the same area as the page it was merged
 * into, except `/admin/setup/cancellation` (`support`), a page of links to two
 * `membership` pages and Email Messages; its destination needs `membership`,
 * so the merge narrows who reaches that content and widens nothing.
 *
 * Type-only imports from `./index`, so there is no runtime cycle; relative
 * imports only (see `release.ts`).
 */
import type { AdminRetiredPage } from "./define";
import type { AdminPageAnchor, AdminPageId, AdminPageTab } from "./index";

/** Identity at runtime; ties `tab` and `anchor` to what `mergedInto` declares. */
function retire<const Id extends AdminPageId>(
  page: AdminRetiredPage<Id, AdminPageTab<Id>, AdminPageAnchor<Id>>,
): AdminRetiredPage<Id> {
  return page;
}

export const ADMIN_RETIRED_PAGES: readonly AdminRetiredPage<AdminPageId>[] = [
  retire({
    oldPath: "/admin/family-suggestions",
    label: "Family Suggestions",
    mergedInto: "family-groups",
    tab: "suggestions",
  }),
  retire({
    oldPath: "/admin/membership-cancellation",
    label: "Membership Cancellation Settings",
    mergedInto: "membership-cancellations",
    tab: "settings",
  }),
  retire({
    // Its three cards: the settings (now this tab), the request queue (the
    // other tab) and Email Messages (linked from this tab).
    oldPath: "/admin/setup/cancellation",
    label: "Cancellation Setup",
    mergedInto: "membership-cancellations",
    tab: "settings",
  }),
  retire({
    oldPath: "/admin/setup/booking-rules",
    label: "Booking Rules",
    mergedInto: "bookings-setup",
  }),
  retire({
    oldPath: "/admin/setup/integrations",
    label: "Integrations Readiness",
    mergedInto: "health",
    anchor: "integration-readiness",
  }),
];
